import argparse
from datetime import date, datetime, timedelta
import json
from pathlib import Path
import sqlite3
from urllib.parse import parse_qs, urlparse

import calendar_import
import config
import database


def _label(value):
    """Compare explicit labels without fuzzy matching or treating empty text as a wildcard."""
    if value is None:
        return ''
    if not isinstance(value, str):
        raise ValueError('Official labels must be text.')
    return value.strip().casefold()


def _clock(value):
    """Validate the existing naive Zurich database timestamp format."""
    if not isinstance(value, str):
        raise ValueError('Evidence timestamps must use the database time format.')
    try:
        parsed = datetime.strptime(value, config.DB_TIME_FORMAT)
    except ValueError:
        raise ValueError('Evidence timestamps must use the database time format.') from None
    if database.to_db_text(parsed) != value:
        raise ValueError('Evidence timestamps must use the database time format.')
    return parsed


def _source_range(url):
    """Accept only the observed public schedule endpoint and explicit complete date queries."""
    if not isinstance(url, str):
        raise ValueError('Evidence requires the official public schedule URL.')
    parsed = urlparse(url)
    endpoint = config.UNISPORT_SCHEDULE_API_URL
    if url.split('?')[0] != endpoint or parsed.fragment:
        raise ValueError('Evidence requires the official public schedule URL.')
    params = parse_qs(parsed.query, keep_blank_values=True)
    required = {'startDateMin', 'startDateMax', 'showBookingsFull', 'showCourses'}
    if set(params) != required or any(len(value) != 1 for value in params.values()):
        raise ValueError('Evidence requires an explicit unfiltered date query.')
    if params['showBookingsFull'] != ['true'] or params['showCourses'] != ['true']:
        raise ValueError('Evidence must include full bookings and courses.')
    try:
        first = date.fromisoformat(params['startDateMin'][0])
        last = date.fromisoformat(params['startDateMax'][0])
    except ValueError:
        raise ValueError('Evidence date queries must use ISO dates.') from None
    if last < first or (last - first).days >= config.DAYS_PER_WEEK:
        raise ValueError('Each evidence query must cover at most one week.')
    return first, last


def _public_appointment(row):
    """Select identity and dated evidence; ignore prices, supervisors and participant counts."""
    if not isinstance(row, dict) or not isinstance(row.get('linkedProduct'), dict):
        raise ValueError('Official appointments need an explicit activity product.')
    product = row['linkedProduct']
    for value in (row.get('id'), row.get('linkedProductId'), product.get('id')):
        if type(value) is not int or value <= 0:
            raise ValueError('Official appointment and product IDs must be positive integers.')
    if row['linkedProductId'] != product['id'] or not _label(product.get('description')):
        raise ValueError('Official activity identity is inconsistent.')
    try:
        start = datetime.fromisoformat(row['startDate'])
        end = datetime.fromisoformat(row['endDate'])
    except (KeyError, TypeError, ValueError):
        raise ValueError('Official appointments need explicit start and end timestamps.') from None
    if start.tzinfo is None or end.tzinfo is None or end < start:
        raise ValueError('Official timestamps must be ordered and include their time zone.')
    start = calendar_import.to_local_naive(start)
    end = calendar_import.to_local_naive(end)
    end += timedelta(minutes=config.UNISPORT_END_OFFSET_MINUTES)
    if end <= start:
        raise ValueError('Official training duration must be positive.')
    return {'booking_id': row['id'], 'product_id': product['id'],
            'public_title': product['description'], 'description': _label(row.get('description')),
            'start': database.to_db_text(start), 'end': database.to_db_text(end)}


def _observations(snapshots, now):
    """Validate complete snapshots before writes and deduplicate stable official appointment IDs."""
    if not isinstance(snapshots, list) or not snapshots:
        raise ValueError('Supply at least one complete public schedule snapshot.')
    observations, seen = {}, {}
    total = 0
    for snapshot in snapshots:
        if not isinstance(snapshot, dict):
            raise ValueError('A schedule snapshot must be an object.')
        first, last = _source_range(snapshot.get('source_url'))
        stamp = _clock(snapshot.get('checked_at'))
        if stamp > now:
            raise ValueError('An evidence check cannot be dated in the future.')
        payload = snapshot.get('payload')
        if not isinstance(payload, dict) or not isinstance(payload.get('data'), list):
            raise ValueError('The official schedule snapshot is incomplete.')
        rows = payload['data']
        if (not rows or payload.get('count') != len(rows) or payload.get('total') != len(rows)
                or payload.get('page') != 1 or payload.get('pageCount') != 1):
            raise ValueError('Use a complete, nonempty, single-page official schedule response.')
        total += len(rows)
        if total > config.MAX_RECORDS_PER_SOURCE:
            raise ValueError('The evidence exceeds the active source record limit.')
        for row in rows:
            observed = _public_appointment(row)
            booking_id = observed['booking_id']
            if booking_id in seen and seen[booking_id] != observed:
                raise ValueError('Repeated official appointment IDs have conflicting evidence.')
            seen[booking_id] = observed.copy()
            # The live endpoint also returned next-Monday rows; respect our requested dates.
            if not first <= date.fromisoformat(observed['start'][:10]) <= last:
                continue
            observed.update(source_url=snapshot['source_url'], checked_at=snapshot['checked_at'])
            existing = observations.get(booking_id)
            if existing is None or observed['checked_at'] > existing['checked_at']:
                observations[booking_id] = observed
    return list(observations.values())


def _approved_patterns(approvals):
    """Require one explicitly reviewed public product and appointment description per pattern."""
    if not isinstance(approvals, list):
        raise ValueError('Course approvals must be a list.')
    result = {}
    for approval in approvals:
        if not isinstance(approval, dict):
            raise ValueError('A course approval must be an object.')
        external_id = approval.get('external_id')
        product_id = approval.get('product_id')
        if (not isinstance(external_id, str)
                or not external_id.startswith(config.HISTORY_PATTERN_PREFIX)
                or type(product_id) is not int or product_id <= 0
                or not _label(approval.get('public_title'))
                or 'appointment_description' not in approval or external_id in result):
            raise ValueError('Each pattern requires one unique explicit course approval.')
        result[external_id] = (product_id, _label(approval['public_title']),
                               _label(approval['appointment_description']))
    return result


def _candidate_matches(connection, observations, approvals, now, counts):
    """Find exact dated candidates and reject any official appointment claimed more than once."""
    index = {}
    for observed in observations:
        key = (observed['product_id'], _label(observed['public_title']),
               observed['description'], observed['start'])
        index.setdefault(key, []).append(observed)
    rows = connection.execute('''SELECT e.*,s.external_id,p.kind,p.verification_url,p.verified_at
        FROM events e JOIN series s ON s.id=e.series_id
        LEFT JOIN event_provenance p ON p.event_id=e.id
        WHERE s.source=? AND substr(s.external_id,1,?)=? AND e.start_time>=? ORDER BY e.id''',
        ('unisport', len(config.HISTORY_PATTERN_PREFIX), config.HISTORY_PATTERN_PREFIX,
         database.to_db_text(now))).fetchall()
    matches, claims = [], {}
    for row in rows:
        approved = approvals.get(row['external_id'])
        if approved is None:
            counts['n_unreviewed'] += 1
            continue
        candidates = index.get(approved + (row['start_time'],), [])
        if len(candidates) != 1:
            counts['n_unmatched' if not candidates else 'n_ambiguous'] += 1
            continue
        observed = candidates[0]
        matches.append((row, observed))
        booking_id = observed['booking_id']
        claims[booking_id] = claims.get(booking_id, 0) + 1
    unique = []
    for row, observed in matches:
        if claims[observed['booking_id']] != 1:
            counts['n_ambiguous'] += 1
        else:
            unique.append((row, observed))
    return unique


def _verify_one(connection, row, observed):
    """Upgrade provenance and an estimated end while preserving manual changes and newer proof."""
    if row['kind'] not in ('projected', 'website'):
        return 'n_protected'
    if not row['end_is_estimated'] and row['end_time'] != observed['end']:
        return 'n_protected'
    if row['kind'] == 'website':
        if row['verified_at'] > observed['checked_at']:
            return 'n_protected'
        if (row['verification_url'] == observed['source_url']
                and row['verified_at'] == observed['checked_at']
                and not row['end_is_estimated']):
            return 'n_existing'
        if row['verified_at'] == observed['checked_at']:
            return 'n_protected'
    if row['end_is_estimated']:
        connection.execute('UPDATE events SET end_time=?,end_is_estimated=? WHERE id=?',
                           (observed['end'], 0, row['id']))
    # Course: A07 – bound parameters and one transaction preserve IDs, evidence and relationships.
    connection.execute('''UPDATE event_provenance
        SET kind=?,verification_url=?,verified_at=? WHERE event_id=?''',
        ('website', observed['source_url'], observed['checked_at'], row['id']))
    return 'n_updated'


def verify_training_events(connection, snapshots, approvals, now=None):
    """Verify only uniquely matched dates, with no reconciliation, deletion or availability guess.

    :param connection: initialized SQLite connection without a pending caller transaction
    :param snapshots: private complete official responses with source_url and checked_at
    :param approvals: explicit pattern/product/public-title/appointment-description mappings
    :param now: injected naive Zurich clock
    :return: aggregate counts without private source text
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before verifying appointments.')
    now = config.local_now(now)
    observations = _observations(snapshots, now)
    reviewed = _approved_patterns(approvals)
    counts = dict.fromkeys(('n_updated', 'n_existing', 'n_unreviewed', 'n_unmatched',
                            'n_ambiguous', 'n_protected'), 0)
    counts['n_observations'] = len(observations)
    matches = _candidate_matches(connection, observations, reviewed, now, counts)
    with connection:
        for row, observed in matches:
            counts[_verify_one(connection, row, observed)] += 1
    return counts


def main():
    """Apply a privately reviewed evidence package without fetching data or publishing anything."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('evidence', type=Path)
    parser.add_argument('--database', type=Path, default=config.TRAINING_HISTORY_DB)
    options = parser.parse_args()
    if not options.database.is_file():
        parser.exit(1, 'The private forecast database does not exist.\n')
    connection = None
    try:
        raw = options.evidence.read_bytes()
        if len(raw) > config.MAX_TRAINING_VERIFICATION_BYTES:
            raise ValueError('The verification package is too large.')
        package = json.loads(raw)
        if not isinstance(package, dict):
            raise ValueError('The verification package must be an object.')
        connection = database.get_connection(options.database)
        report = verify_training_events(connection, package.get('snapshots'),
                                        package.get('course_approvals'))
    except (OSError, sqlite3.Error):
        parser.exit(1, 'Could not read or apply the private verification package.\n')
    except (UnicodeError, ValueError):
        parser.exit(1, 'Invalid or incomplete official verification evidence.\n')
    finally:
        if connection is not None:
            connection.close()
    print(json.dumps(report, sort_keys=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
